fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let gx: i32 = 40;
    let gy: i32 = 60;
    let cs: i32 = 44;
    let mut mask: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        let cx: i32 = (px - gx) / cs;
        let cy: i32 = (py - gy) / cs;
        if px >= gx && py >= gy && cx < 4 && cy < 4 {
            mask = mask ^ (1 << (cy * 4 + cx));
            host::display::state_set(0, mask);
        }
    }
    host::display::state_set(1, down);
    host::display::clear(0x101010);
    let mut i: i32 = 0;
    let mut on: i32 = 0;
    while i < 16 {
        let x: i32 = gx + (i % 4) * cs;
        let y: i32 = gy + (i / 4) * cs;
        if ((mask >> i) & 1) == 1 {
            host::display::fill_rect(x + 2, y + 2, cs - 4, cs - 4, 0x00cc66);
            on = on + 1;
        } else {
            host::display::fill_rect(x + 2, y + 2, cs - 4, cs - 4, 0x303030);
            host::display::fill_rect(x + 4, y + 4, cs - 8, cs - 8, 0x101010);
        }
        i = i + 1;
    }
    host::display::draw_string(40, 20, "ON", 0x808080, 2);
    host::display::draw_number(80, 20, on, 0xffffff, 2);
    host::display::present();
}
